<?php
require __DIR__.'/../app/bootstrap.php';refresh_user();require_login('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$section=post_value('section');if($section==='printer'){$paper=post_value('paper_size');$colour=post_value('colour_options');$address=post_value('printer_email');if(!in_array($paper,['A4','A3','Letter','Legal','4x6'],true)||!in_array($colour,['Colour','Black & White'],true)||($address!==''&&!filter_var($address,FILTER_VALIDATE_EMAIL))){flash('error','Check paper, colour, or printer email address.');redirect('/admin/settings.php');}set_setting('paper_size',$paper);set_setting('colour_options',$colour);set_setting('printer_email',$address);flash('success','Epson printer settings saved.');}elseif($section==='mail'){$from=post_value('mail_from');$port=(int)post_value('mail_port');if(!filter_var($from,FILTER_VALIDATE_EMAIL)||$port<1||$port>65535){flash('error','Enter a valid sender email and SMTP port.');redirect('/admin/settings.php');}foreach(['mail_from','mail_from_name','mail_host','mail_port','mail_username','mail_encryption'] as $key)set_setting($key,post_value($key));$password=post_value('mail_password');if($password!=='')set_setting('mail_password',$password);flash('success','Mail settings saved. Leave password blank to keep the current value.');}elseif($section==='database'){flash('info','Database connection details are managed using the server environment (DB_HOST, DB_PORT, DB_NAME, DB_USER, DB_PASS) to avoid storing secrets in the database.');}redirect('/admin/settings.php');}
render_header('Settings Management','admin');page_title('Settings Management','Configure printer delivery and application connections.');
?><div class="settings-stack"><section class="settings-card"><div class="settings-heading"><span class="settings-icon orange">▣</span><div><h2>Epson Printer Settings</h2><p>Defaults applied to new client print requests.</p></div></div><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="section" value="printer"><div class="field-row"><label>Paper size<select name="paper_size"><?php foreach(['A4','A3','Letter','Legal','4x6'] as $o): ?><option <?=$o===setting('paper_size','A4')?'selected':''?>><?=e($o)?></option><?php endforeach; ?></select></label><label>Colour options<select name="colour_options"><?php foreach(['Colour','Black & White'] as $o): ?><option <?=$o===setting('colour_options','Colour')?'selected':''?>><?=e($o)?></option><?php endforeach; ?></select></label></div><label>Epson Email Print address<input type="email" name="printer_email" value="<?=e(setting('printer_email'))?>" placeholder="printer@print.epsonconnect.com"><small>Approved jobs are emailed as an attachment; print settings are included in the subject and message.</small></label><button class="button button-admin">Save printer settings</button></form></section>
<section class="settings-card"><div class="settings-heading"><span class="settings-icon violet">✉</span><div><h2>PHP Mail settings</h2><p>SMTP connection for account and job notifications. Password is write-only.</p></div></div><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="section" value="mail"><div class="field-row"><label>SMTP host<input name="mail_host" value="<?=e(setting('mail_host',''))?>" placeholder="smtp.example.com"></label><label>SMTP port<input name="mail_port" type="number" min="1" max="65535" value="<?=e(setting('mail_port','25'))?>"></label></div><div class="field-row"><label>SMTP username<input name="mail_username" value="<?=e(setting('mail_username'))?>" autocomplete="off"></label><label>SMTP password<input name="mail_password" type="password" value="" autocomplete="new-password" placeholder="Leave blank to keep saved password"></label></div><div class="field-row"><label>Encryption<select name="mail_encryption"><?php foreach(['none'=>'None','tls'=>'STARTTLS','ssl'=>'SSL/TLS'] as $v=>$label): ?><option value="<?=e($v)?>" <?=$v===setting('mail_encryption','none')?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><label>From email<input name="mail_from" type="email" value="<?=e(setting('mail_from',''))?>" required></label></div><label>From name<input name="mail_from_name" value="<?=e(setting('mail_from_name','Print Portal'))?>"></label><div class="notice-card">The application sends mail using a lightweight SMTP client or PHP <code>mail()</code> if no SMTP host is configured. Epson dispatch uses this same transport.</div><button class="button button-admin">Save mail settings</button></form></section>
<section class="settings-card"><div class="settings-heading"><span class="settings-icon blue">⌘</span><div><h2>SQL Database settings</h2><p>Connection credentials are set by the server, not stored in the portal.</p></div></div><div class="db-env-list"><div><span>DB_HOST</span><strong><?=e(getenv('DB_HOST')?:'127.0.0.1')?> · <?=e(getenv('DB_PORT')?:'3306')?></strong></div><div><span>DB_NAME</span><strong><?=e(getenv('DB_NAME')?:'print_portal')?></strong></div><div><span>DB_USER</span><strong><?=e(getenv('DB_USER')?:'root')?></strong></div><div><span>DB_PASS</span><strong>•••••••• (stored in environment)</strong></div></div><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="section" value="database"><button class="button button-soft">View connection guidance</button></form></section></div><?php render_footer();
